const events=[{id:"ok-naha-haarii",pref:P,name:T("나하 하리","那覇ハーリー"),area:A.naha,months:[5],timing:T("2026년 5월 3~5일","2026年5月3〜5日"),scheduleType:T("2026년 개최 완료","2026年開催済み"),type:T("용선·항구축제·전통","爬龍船・港祭・伝統"),description:T("오키나와 전통 용선 하리 경기와 일반 체험승선·먹거리 부스가 중심인 나하항의 대표 봄축제입니다. 2026년에는 예년의 무대공연과 불꽃은 실시하지 않았습니다.","沖縄伝統の爬龍船競漕、一般体験乗船、飲食・物販出店を中心とする那覇港の代表的な春祭りです。2026年は例年のステージイベントと花火は実施されませんでした。"),source:"https://www.naha-navi.or.jp/wp-content/uploads/2026/02/8231152854d0fc21b1d9526cae4a92e1.pdf"},{id:"ok-churaumi-fireworks",pref:P,name:T("해양박공원 추라우미 불꽃축제","海洋博公園美ら海花火大会"),area:A.north,months:[7],timing:T("2026년 7월 4일","2026年7月4日"),scheduleType:T("2026년 개최 완료","2026年開催済み"),type:T("불꽃·해양박공원·여름","花火・海洋博公園・夏"),description:T("추라우미수족관이 있는 해양박공원 해안을 배경으로 열리는 대형 여름 불꽃행사입니다.","美ら海水族館のある海洋博公園の海辺を舞台に開催される大型夏花火イベントです。"),source:"https://churaumi.okinawa/"},{id:"ok-eisa",pref:P,name:T("오키나와 전도 에이사마쓰리","沖縄全島エイサーまつり"),area:A.central,months:[9],timing:T("2026년 9월 4~6일","2026年9月4〜6日"),scheduleType:T("2026년 개최 완료","2026年開催済み"),type:T("에이사·행렬·불꽃","エイサー・道ジュネー・花火"),description:T("오키나와 각지 청년회의 에이사팀이 고자에 모여 미치주네와 대형 공연을 펼치는 대표 전통예능 축제입니다.","沖縄各地の青年会エイサーがコザに集まり、道ジュネーと大規模演舞を披露する代表的な伝統芸能祭です。"),source:"https://www.kozaweb.jp/categoryPages/27"},{id:"ok-tug",pref:P,name:T("나하 대줄다리기마쓰리","那覇大綱挽まつり"),area:A.naha,months:[10],timing:T("2026년 10월 10~12일 · 대줄다리기 11일","2026年10月10〜12日・大綱挽11日"),scheduleType:T("2026년 공식 일정","2026年公式日程"),type:T("대줄다리기·깃발행렬·국제거리","大綱挽・旗頭・国際通り"),description:T("국제거리 깃발행렬과 국도58호 구모지교차로의 거대한 줄다리기가 중심인 나하 가을 대표축제입니다.","国際通りの旗頭行列と国道58号久茂地交差点の巨大綱引きを中心とする那覇の秋を代表する祭りです。"),source:"https://www.naha-navi.or.jp/magazine/2026/09/49306/"},{id:"ok-shuri",pref:P,name:T("슈리성 복흥제","首里城復興祭"),area:A.naha,months:[11],timing:T("2026년 11월 1~3일","2026年11月1〜3日"),scheduleType:T("2026년 공식 일정","2026年公式日程"),type:T("왕조행렬·전통예능·복원","王朝行列・伝統芸能・復元"),description:T("정전 복원 완공의 해에 약 700명이 참여하는 류큐왕조회권행렬과 국왕·왕비 출어, 고식행렬이 이어지는 특별한 해의 행사입니다.","正殿復元完成の年に約700名の琉球王朝絵巻行列、国王・王妃出御、古式行列が続く特別な年の祭りです。"),source:"https://oki-park.jp/shurijo/events/detail/10970"},{id:"ok-whale",pref:P,name:T("게라마 고래관찰 시즌","慶良間ホエールウォッチング"),area:A.kerama,months:[1,2,3],timing:T("예년 1~3월","例年1〜3月"),scheduleType:T("계절 참고","季節目安"),type:T("혹등고래·바다·생태","ザトウクジラ・海・生態"),description:T("겨울철 번식을 위해 게라마 해역으로 오는 혹등고래를 전문 보트에서 관찰하는 계절 체험입니다.","冬に繁殖のため慶良間海域へ来るザトウクジラを専門船から観察する季節体験です。"),source:"https://www.visitokinawajapan.com/"},{id:"ok-miyako-sea",pref:P,name:T("미야코지마 바다열기","宮古島の海びらき"),area:A.miyako,months:[4],timing:T("2026년 4월 5일","2026年4月5日"),scheduleType:T("2026년 개최 완료","2026年開催済み"),type:T("바다열기·안전기원·봄","海びらき・安全祈願・春"),description:T("2026년 4월 5일 요나하마에하마비치에서 열릴 예정이었지만 악천후 예보로 야외행사는 취소되고, 일부 프로그램을 이라부섬 다목적 실내운동장으로 옮겨 진행했습니다.","2026年4月5日に与那覇前浜ビーチで開催予定でしたが、悪天候予報のため屋外行事は中止となり、一部プログラムを伊良部島の多目的屋内運動場へ変更して実施しました。"),source:"https://miyako-guide.net/post-8707/"}];
const intros={[P]:["",T("류큐왕국의 역사와 세계유산, 얀바루 원시림과 산호초 바다, 게라마·미야코·야에야마의 섬 풍경까지 지역별 색이 뚜렷해 한 번의 여행으로 모두 보기 어려운 대형 섬 여행권입니다.","琉球王国の歴史と世界遺産、やんばるの原生林とサンゴ礁、慶良間・宮古・八重山の島景観まで地域ごとの個性が強く、一度の旅行ですべてを見るのが難しい大きな島旅エリアです。")],[A.naha]:["NAHA · SOUTH",T("슈리성·국제거리의 왕도시 문화와 남부 전쟁사·성지·종유동을 함께 보는 오키나와 첫 방문의 기본권역입니다.","首里城・国際通りの王都文化と南部の戦争史・聖地・鍾乳洞を一緒に見る沖縄初訪問の基本エリアです。")],[A.central]:["CENTRAL · WEST COAST",T("미군문화와 에이사·도자기·세계유산 구스쿠, 서해안 석양이 함께 섞여 현대 오키나와의 여러 얼굴을 보기 좋은 권역입니다.","米軍文化、エイサー、焼物、世界遺産グスク、西海岸の夕日が混ざり合い、現代沖縄の多面性を感じやすいエリアです。")],[A.north]:["YANBARU · NORTH",T("추라우미수족관과 세계유산 나키진성, 고우리섬의 바다에서 얀바루 국립공원의 숲·카르스트까지 자연 비중이 높은 북부권입니다.","美ら海水族館、世界遺産今帰仁城、古宇利島の海から、やんばる国立公園の森・カルストまで自然の比重が高い北部エリアです。")],[A.kerama]:["KERAMA",T("나하에서 배로 접근하는 작은 섬들에서 게라마블루 해변과 산호초, 겨울철 혹등고래를 즐기는 해양 중심 여행권입니다.","那覇から船で渡る小島で、ケラマブルーのビーチ、サンゴ礁、冬のザトウクジラを楽しむ海中心の旅行エリアです。")],[A.miyako]:["MIYAKO",T("긴 백사장과 미야코블루, 섬들을 잇는 대교와 석회암 지형이 중심인 드라이브·해변형 섬 여행권입니다.","長い白砂浜と宮古ブルー、島々を結ぶ橋、石灰岩地形が中心のドライブ・ビーチ型の島旅エリアです。")],[A.yaeyama]:["YAEYAMA",T("이시가키를 거점으로 다케토미·이리오모테·하테루마까지 배로 연결하며 전통마을·맹그로브·폭포·산호초를 즐기는 군도 여행권입니다.","石垣島を拠点に竹富・西表・波照間まで船でつなぎ、伝統集落、マングローブ、滝、サンゴ礁を楽しむ群島旅行エリアです。")]};const heroes={[A.naha]:3600,[A.central]:3609,[A.north]:3616,[A.kerama]:3624,[A.miyako]:3626,[A.yaeyama]:3631};
